{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is neutral or negative (sentiment ≤ 0.00) to account for risk aversion or market cooling.",
    "Reduce forecast overshoots (especially after spikes) by 5–10% in the immediate 5–7 day horizon to prevent overreaction.",
    "Apply mean reversion bias: if forecast deviates > ±10% from recent 7-day average, adjust toward that average with decay factor of 0.8 per day.",
    "For 30-day horizon, penalize over-optimistic forecasts (e.g., > +15% above recent 14-day high) by reducing forecast by 10–15% if sentiment is weak or flat.",
    "Lag correction: if true outcome is lower than forecast by >5% over 3–5 days, reduce next forecast by 2–3% to account for delayed market response."
  ]
}
